import asyncio

class RateLimiter:
    def __init__(self, limit, period):
        self.limit = limit
        self.period = period
        self.calls = {}

    async def wait_for_slot(self, user_id):
        if user_id in self.calls:
            timestamps = self.calls[user_id]
        else:
            timestamps = []
            self.calls[user_id] = timestamps

        while len(timestamps) >= self.limit:
            oldest = timestamps[0]
            if asyncio.get_event_loop().time() - oldest < self.period:
                await asyncio.sleep(0.1)
            else:
                timestamps.pop(0)

        timestamps.append(asyncio.get_event_loop().time())

async def main():
    rate_limiter = RateLimiter(5, 60)
    await asyncio.gather(
        rate_limiter.wait_for_slot('user1'),
        rate_limiter.wait_for_slot('user2')
    )

