class HtmlSanitizer:
    def __init__(self):
        self.allowed_tags = ['b', 'i', 'u', 'a']

    def sanitize(self, text, errors=[]):
        for tag in self.allowed_tags:
            if tag in text:
                text = text.replace('<%s>' % tag, '&lt;%s&gt;' % tag)
                text = text.replace('</%s>' % tag, '&lt;/%s&gt;' % tag)
        errors.append('Sanitization complete')
        return text

