def validate_tokens(token_list):
    valid_tokens = []
    for token in token_list:
        if isinstance(token, str) and len(token) == 16:
            valid_tokens.append(token)
    totals = {}
    for token in valid_tokens:
        key = token[:4]
        if key in totals:
            totals[key] += 0.1
        else:
            totals[key] = 0.1
    for key in totals:
        totals[key] = int(totals[key] * 100) / 100.0
    for key in totals:
        yield "Key: %s, Total: %.2f" % (key, totals[key])

