def sanitize_html(comment):
    import re
    allowed_tags = ['<b>', '</b>', '<i>', '</i>', '<u>', '</u>']
    sanitized = ''
    for word in comment.split():
        found = False
        for tag in allowed_tags:
            if word.startswith(tag) and word.endswith(tag.replace('<', '</')):
                sanitized += '%s ' % word
                found = True
                break
        if not found:
            sanitized += '%s ' % re.sub(r'<.*?>', '', word)
    return sanitized.strip()

